import Mathlib

/-!
# Discrete Optimal Transport: the Kantorovich / 1-Wasserstein distance is a pseudometric

This file develops, from scratch, the theory of optimal transport on a finite type
`α`.  A *probability distribution* is a nonnegative function `μ : α → ℝ` summing to `1`;
a *coupling* (transport plan) of two distributions `μ`, `ν` is a nonnegative matrix
`π : α → α → ℝ` whose row sums recover `μ` and whose column sums recover `ν`; and the
*Kantorovich cost* of a plan with respect to a cost function `d : α → α → ℝ` is
`∑ i, ∑ j, π i j * d i j`.  The **1-Wasserstein distance**

`Wass d μ ν = sInf { transportCost d π | π is a coupling of μ ν }`

is the infimum of the cost over all couplings.

The main results are that, when `d` is a (pseudo)metric on `α`, `Wass d` is a
pseudometric on probability distributions:

* `Wass_nonneg`            : `0 ≤ Wass d μ ν`;
* `Wass_self_eq_zero`      : `Wass d μ μ = 0`;
* `Wass_comm`              : `Wass d μ ν = Wass d ν μ`;
* `Wass_triangle`          : `Wass d μ ξ ≤ Wass d μ ν + Wass d ν ξ`.

The triangle inequality is the discrete **gluing lemma**: given couplings `π` of
`(μ,ν)` and `ρ` of `(ν,ξ)`, the matrix `glue π ρ ν i k = ∑ j, π i j * ρ j k / ν j`
is a coupling of `(μ,ξ)` whose cost is at most `cost π + cost ρ`.

-- !-- Lab Notes -- !--
Hypothesis (Hypothesizer): on a finite space the Kantorovich LP is finite-dimensional,
so the Wasserstein distance can be defined as `sInf` of a nonempty, bounded-below cost
set and shown to be a genuine pseudometric without any measure-theoretic machinery
(Mathlib has couplings of measures but not this discrete metric statement).

Experiment 1 (product / diagonal plans): the product plan `μ ⊗ ν` witnesses that the
cost set is always nonempty (hence `sInf` is meaningful); the diagonal plan witnesses
`Wass d μ μ = 0` when `d` vanishes on the diagonal.  Both verified.

Experiment 2 (symmetry): transposing a plan turns a coupling of `(μ,ν)` into a coupling
of `(ν,μ)` of equal cost when `d` is symmetric, so the two cost sets coincide and the
two infima agree.  Verified.

Experiment 3 (gluing): the key subtlety is division by `ν j`.  Working over `ℝ` we use
the convention `x / 0 = 0`; crucially, in a valid coupling `π i j = 0` whenever
`ν j = 0` (a column with zero mass is empty), so the degenerate terms vanish and no
`if`-guard is needed in the definition of `glue`.  This made the algebra dramatically
cleaner than an explicit case split.  Verified.

Insight: the triangle inequality follows from the *uniform* bound
`Wass d μ ξ ≤ cost π + cost ρ` (valid for every pair of plans) by two applications of
`le_csInf`; no optimal plan needs to be exhibited, sidestepping any compactness/attainment
argument.
-/

open Finset

namespace DiscreteOT

variable {α : Type*} [Fintype α]

/-- A (discrete) probability distribution on a finite type. -/
def IsProbDist (μ : α → ℝ) : Prop :=
  (∀ i, 0 ≤ μ i) ∧ ∑ i, μ i = 1

/-- A coupling (transport plan) of `μ` and `ν`: a nonnegative matrix with the right
marginals. -/
def IsCoupling (μ ν : α → ℝ) (π : α → α → ℝ) : Prop :=
  (∀ i j, 0 ≤ π i j) ∧ (∀ i, ∑ j, π i j = μ i) ∧ (∀ j, ∑ i, π i j = ν j)

/-- The Kantorovich cost of a transport plan `π` under cost function `d`. -/
def transportCost (d : α → α → ℝ) (π : α → α → ℝ) : ℝ :=
  ∑ i, ∑ j, π i j * d i j

/-- The set of costs achievable by couplings of `μ` and `ν`. -/
def costSet (d : α → α → ℝ) (μ ν : α → ℝ) : Set ℝ :=
  { c | ∃ π, IsCoupling μ ν π ∧ transportCost d π = c }

/-- The Kantorovich / 1-Wasserstein distance between `μ` and `ν`. -/
noncomputable def Wass (d : α → α → ℝ) (μ ν : α → ℝ) : ℝ :=
  sInf (costSet d μ ν)

/-- The independent (product) coupling. -/
def productCoupling (μ ν : α → ℝ) : α → α → ℝ := fun i j => μ i * ν j

/-- The diagonal coupling of a distribution with itself. -/
def diagCoupling [DecidableEq α] (μ : α → ℝ) : α → α → ℝ := fun i j => if i = j then μ i else 0

/-- The glued coupling used in the gluing lemma. -/
noncomputable def glue (π ρ : α → α → ℝ) (ν : α → ℝ) : α → α → ℝ :=
  fun i k => ∑ j, π i j * ρ j k / ν j

/-! ### Basic facts about couplings -/

/-- A column with zero `ν`-mass is empty in any coupling of `(μ, ν)`. -/
lemma coupling_col_eq_zero {μ ν : α → ℝ} {π : α → α → ℝ} (h : IsCoupling μ ν π) {j : α}
    (hj : ν j = 0) : ∀ i, π i j = 0 := by
  cases h;
  exact fun i => le_antisymm ( by simpa [ hj ] using Finset.single_le_sum ( fun i _ => ‹∀ i j, 0 ≤ π i j› i j ) ( Finset.mem_univ i ) |> le_trans <| by aesop ) ( by solve_by_elim )

/-- A row with zero `ν`-mass is empty in any coupling of `(ν, ξ)`. -/
lemma coupling_row_eq_zero {ν ξ : α → ℝ} {ρ : α → α → ℝ} (h : IsCoupling ν ξ ρ) {j : α}
    (hj : ν j = 0) : ∀ k, ρ j k = 0 := by
  exact fun k => by simpa [ * ] using Finset.sum_eq_zero_iff_of_nonneg ( fun i _ => h.1 j i ) |>.1 ( show ∑ i, ρ j i = 0 from by simpa [ * ] using h.2.1 j ) k;

/-- The product coupling is a valid coupling. -/
lemma productCoupling_isCoupling {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    IsCoupling μ ν (productCoupling μ ν) := by
  refine' ⟨ _, _, _ ⟩ <;> simp_all +decide [ productCoupling ];
  · exact fun i j => mul_nonneg ( hμ.1 i ) ( hν.1 j );
  · exact fun i => by rw [ ← Finset.mul_sum _ _ _, hν.2, mul_one ] ;
  · simp +decide [ ← Finset.sum_mul, hμ.2 ]

/-- The diagonal coupling is a valid coupling of `μ` with itself. -/
lemma diagCoupling_isCoupling [DecidableEq α] {μ : α → ℝ} (hμ : IsProbDist μ) :
    IsCoupling μ μ (diagCoupling μ) := by
  refine' ⟨ fun i j => _, fun i => _, fun j => _ ⟩ <;> simp_all +decide [ diagCoupling ];
  split_ifs <;> [ exact hμ.1 _; exact le_rfl ]

/-! ### Cost set: nonempty and bounded below -/

/-- The cost set is nonempty (witnessed by the product coupling). -/
lemma costSet_nonempty {d : α → α → ℝ} {μ ν : α → ℝ}
    (hμ : IsProbDist μ) (hν : IsProbDist ν) : (costSet d μ ν).Nonempty := by
  exact ⟨ _, ⟨ _, productCoupling_isCoupling hμ hν, rfl ⟩ ⟩

/-- Nonnegativity of the transport cost when both the plan and the cost are nonnegative. -/
lemma transportCost_nonneg {d : α → α → ℝ} {π : α → α → ℝ}
    (hd : ∀ i j, 0 ≤ d i j) (hπ : ∀ i j, 0 ≤ π i j) : 0 ≤ transportCost d π := by
  exact Finset.sum_nonneg fun i _ => Finset.sum_nonneg fun j _ => mul_nonneg ( hπ i j ) ( hd i j )

/-- The cost set is bounded below by `0` when the cost function is nonnegative. -/
lemma costSet_bddBelow {d : α → α → ℝ} {μ ν : α → ℝ}
    (hd : ∀ i j, 0 ≤ d i j) : BddBelow (costSet d μ ν) := by
  by_contra h;
  -- By definition of `costSet`, we know that every element in `costSet d μ ν` is of the form `transportCost d π` for some coupling `π` of `μ` and `ν`.
  have h_cost_set : ∀ c ∈ costSet d μ ν, ∃ π : α → α → ℝ, IsCoupling μ ν π ∧ c = transportCost d π := by
    exact fun c hc => by obtain ⟨ π, hπ, rfl ⟩ := hc; exact ⟨ π, hπ, rfl ⟩ ;
  exact h ⟨ 0, fun c hc => by obtain ⟨ π, hπ, rfl ⟩ := h_cost_set c hc; exact transportCost_nonneg hd hπ.1 ⟩

/-! ### Nonnegativity and self-distance -/

lemma Wass_nonneg {d : α → α → ℝ} {μ ν : α → ℝ} (hd : ∀ i j, 0 ≤ d i j) :
    0 ≤ Wass d μ ν := by
  apply_rules [ Real.sInf_nonneg ];
  rintro x ⟨ π, hπ, rfl ⟩ ; exact Finset.sum_nonneg fun i hi => Finset.sum_nonneg fun j hj => mul_nonneg ( hπ.1 i j ) ( hd i j ) ;

lemma Wass_self_eq_zero [DecidableEq α] {d : α → α → ℝ} {μ : α → ℝ} (hd : ∀ i j, 0 ≤ d i j)
    (hdiag : ∀ i, d i i = 0) (hμ : IsProbDist μ) : Wass d μ μ = 0 := by
  refine' le_antisymm ( csInf_le _ _ ) ( _ );
  · exact costSet_bddBelow hd;
  · use diagCoupling μ;
    exact ⟨ diagCoupling_isCoupling hμ, by unfold transportCost; simp +decide [ hdiag, diagCoupling ] ⟩;
  · exact Wass_nonneg hd

/-! ### Symmetry -/

lemma Wass_comm {d : α → α → ℝ} {μ ν : α → ℝ} (hsymm : ∀ i j, d i j = d j i) :
    Wass d μ ν = Wass d ν μ := by
  refine' congr_arg _ ( Set.ext _ );
  intro x;
  constructor <;> rintro ⟨ π, hπ, rfl ⟩;
  · refine' ⟨ fun i j => π j i, _, _ ⟩;
    · exact ⟨ fun i j => hπ.1 j i, fun i => by simpa only [ Finset.sum_apply ] using hπ.2.2 i, fun j => by simpa only [ Finset.sum_apply ] using hπ.2.1 j ⟩;
    · unfold transportCost; rw [ Finset.sum_comm ] ; congr; ext; congr; ext; rw [ hsymm ] ;
  · refine' ⟨ fun i j => π j i, _, _ ⟩ <;> simp_all +decide [ IsCoupling, transportCost ];
    exact Finset.sum_comm.trans ( Finset.sum_congr rfl fun _ _ => Finset.sum_congr rfl fun _ _ => by rw [ hsymm ] )

/-! ### The gluing lemma and the triangle inequality -/

/-- The glued plan is nonnegative. -/
lemma glue_nonneg {ν : α → ℝ} {π ρ : α → α → ℝ}
    (hν : ∀ j, 0 ≤ ν j) (hπ : ∀ i j, 0 ≤ π i j) (hρ : ∀ i j, 0 ≤ ρ i j) :
    ∀ i k, 0 ≤ glue π ρ ν i k := by
  exact fun i k => Finset.sum_nonneg fun j _ => div_nonneg ( mul_nonneg ( hπ i j ) ( hρ j k ) ) ( hν j )

/-- The glued plan of two couplings is a coupling of the outer marginals. -/
lemma glue_isCoupling {μ ν ξ : α → ℝ} {π ρ : α → α → ℝ}
    (hν : IsProbDist ν)
    (hπ : IsCoupling μ ν π) (hρ : IsCoupling ν ξ ρ) :
    IsCoupling μ ξ (glue π ρ ν) := by
  refine' ⟨ fun i j => _, fun i => _, fun j => _ ⟩;
  · exact glue_nonneg hν.1 hπ.1 hρ.1 i j;
  · have h_row_sum : ∑ k, glue π ρ ν i k = ∑ j, π i j * (∑ k, ρ j k / ν j) := by
      unfold glue;
      simpa only [ mul_div_assoc, Finset.mul_sum _ _ _ ] using Finset.sum_comm;
    simp_all +decide [ ← Finset.sum_div _ _ _, hρ.2.1 ];
    rw [ ← hπ.2.1 i, Finset.sum_congr rfl ] ; intros ; by_cases hi : ν ‹_› = 0 <;> simp +decide [ hi ];
    exact Eq.symm ( coupling_col_eq_zero hπ hi i );
  · unfold glue;
    rw [ Finset.sum_comm ];
    convert hρ.2.2 j using 2;
    by_cases h : ν ‹_› = 0 <;> simp_all +decide [ div_eq_inv_mul, ← Finset.mul_sum _ _ _, ← Finset.sum_mul, hπ.2.2 ];
    exact Eq.symm ( coupling_row_eq_zero hρ h _ )

/-- The cost of the glued plan is at most the sum of the costs (triangle inequality of `d`). -/
lemma glue_cost_le {d : α → α → ℝ} {ν : α → ℝ} {π ρ : α → α → ℝ}
    (hd : ∀ i j, 0 ≤ d i j) (htri : ∀ i j k, d i k ≤ d i j + d j k)
    (hν : IsProbDist ν) (hπnn : ∀ i j, 0 ≤ π i j) (hρnn : ∀ i j, 0 ≤ ρ i j)
    (hπcol : ∀ j, ∑ i, π i j = ν j) (hρrow : ∀ j, ∑ k, ρ j k = ν j) :
    transportCost d (glue π ρ ν) ≤ transportCost d π + transportCost d ρ := by
  -- By Fubini's theorem, we can interchange the order of summation.
  have h_fubini : ∑ i, ∑ k, ∑ j, (π i j * ρ j k / ν j) * d i k ≤ ∑ j, ∑ i, ∑ k, (π i j * ρ j k / ν j) * (d i j + d j k) := by
    rw [ Finset.sum_comm, Finset.sum_congr rfl fun _ _ => Finset.sum_comm ];
    refine' Finset.sum_comm.trans_le ( Finset.sum_le_sum fun j _ => Finset.sum_comm.trans_le ( Finset.sum_le_sum fun i _ => Finset.sum_le_sum fun k _ => _ ) );
    exact mul_le_mul_of_nonneg_left ( htri i j k ) ( div_nonneg ( mul_nonneg ( hπnn i j ) ( hρnn j k ) ) ( hν.1 j ) );
  -- Distribute the multiplication inside the sum.
  have h_distribute : ∑ j, ∑ i, ∑ k, (π i j * ρ j k / ν j) * (d i j + d j k) = ∑ j, ∑ i, π i j * d i j * (∑ k, ρ j k / ν j) + ∑ j, ∑ k, ρ j k * d j k * (∑ i, π i j / ν j) := by
    simp +decide only [mul_comm, Finset.mul_sum _ _ _, mul_left_comm];
    simp +decide only [mul_div_assoc, add_mul, sum_add_distrib];
    exact congrArg₂ ( · + · ) rfl ( Finset.sum_congr rfl fun _ _ => Finset.sum_comm.trans ( Finset.sum_congr rfl fun _ _ => Finset.sum_congr rfl fun _ _ => by ring ) );
  simp_all +decide [ ← Finset.sum_div _ _ _, ← Finset.sum_mul, transportCost ];
  refine' le_trans h_fubini _;
  rw [ ← Finset.sum_comm ];
  exact add_le_add ( Finset.sum_le_sum fun i _ => mul_le_of_le_one_right ( Finset.sum_nonneg fun _ _ => mul_nonneg ( hπnn _ _ ) ( hd _ _ ) ) ( div_self_le_one _ ) ) ( Finset.sum_le_sum fun i _ => mul_le_of_le_one_right ( Finset.sum_nonneg fun _ _ => mul_nonneg ( hρnn _ _ ) ( hd _ _ ) ) ( div_self_le_one _ ) )

/-- **Triangle inequality** for the discrete Wasserstein distance. -/
lemma Wass_triangle {d : α → α → ℝ} {μ ν ξ : α → ℝ}
    (hd : ∀ i j, 0 ≤ d i j) (htri : ∀ i j k, d i k ≤ d i j + d j k)
    (hμ : IsProbDist μ) (hν : IsProbDist ν) (hξ : IsProbDist ξ) :
    Wass d μ ξ ≤ Wass d μ ν + Wass d ν ξ := by
  have h_le1 : ∀ c ∈ costSet d μ ν, Wass d μ ξ - c ≤ Wass d ν ξ := by
    intro c hc
    obtain ⟨π, hπ⟩ := hc
    have h_a_le_c_plus_sInf : ∀ c' ∈ costSet d ν ξ, Wass d μ ξ ≤ c + c' := by
      intro c' hc'
      obtain ⟨ρ, hρ⟩ := hc'
      have h_glue : transportCost d (glue π ρ ν) ≤ c + c' := by
        convert glue_cost_le hd htri hν hπ.1.1 hρ.1.1 hπ.1.2.2 hρ.1.2.1 using 1 ; aesop;
      exact le_trans ( csInf_le ( costSet_bddBelow hd ) ⟨ _, glue_isCoupling hν hπ.1 hρ.1, rfl ⟩ ) h_glue;
    exact le_csInf ( costSet_nonempty hν hξ ) fun c' hc' => by linarith [ h_a_le_c_plus_sInf c' hc' ] ;
  exact le_of_forall_pos_le_add fun ε εpos => by rcases exists_lt_of_csInf_lt ( costSet_nonempty hμ hν ) ( show Wass d μ ν < Wass d μ ν + ε by linarith ) with ⟨ c, hc, hc' ⟩ ; linarith [ h_le1 c hc ] ;

/-! ### The discrete (0/1) metric: Wasserstein distance equals total variation

-- !-- Lab Notes -- !--
Hypothesis (Hypothesizer): for the discrete metric `d i j = if i = j then 0 else 1`,
the 1-Wasserstein distance should collapse to the **total variation distance**
`TVDist μ ν = ½ ∑ i, |μ i - ν i|`.  This is the discrete avatar of the classical
identity `W₁ = TV` for the trivial metric.

Experiment 4 (lower bound): under the discrete metric the cost of any plan `π` is
`1 - ∑ i, π i i` (mass kept off the diagonal), and `π i i ≤ min (μ i) (ν i)` because a
diagonal entry is bounded by both marginals.  Summing, `∑ i, π i i ≤ ∑ i, min (μ i) (ν i)
= 1 - TV`, giving `cost π ≥ TV`.  Verified.

Experiment 5 (upper bound / optimal plan): keep `min (μ i) (ν i)` on the diagonal and
couple the two leftover masses (the positive parts `μ i - min` and `ν j - min`) by an
independent plan rescaled by `T = TVDist μ ν`.  The product structure makes the
off-diagonal cost exactly `T` because the positive parts of `μ - ν` and `ν - μ` have
disjoint support, so `∑ i, (μ i - min)(ν i - min) = 0`.  The degenerate case `T = 0`
(`μ = ν`) is handled automatically by the `x / 0 = 0` convention.  Verified.

Insight: combining both bounds, `Wass discreteMetric = TVDist` exactly, and since
`TVDist μ ν = 0 ↔ μ = ν` for probability vectors, this upgrades the pseudometric to a
genuine metric (identity of indiscernibles) on the simplex.
-/

section Discrete

variable [DecidableEq α]

/-- The discrete (0/1) metric on a finite type. -/
def discreteMetric : α → α → ℝ := fun i j => if i = j then 0 else 1

/-- The total variation distance between two distributions. -/
noncomputable def TVDist (μ ν : α → ℝ) : ℝ := (1/2) * ∑ i, |μ i - ν i|

/-- The optimal transport plan for the discrete metric: keep `min (μ i) (ν i)` on the
diagonal and couple the leftover positive parts independently. -/
noncomputable def tvCoupling (μ ν : α → ℝ) : α → α → ℝ :=
  fun i j => (if i = j then min (μ i) (ν i) else 0)
    + (μ i - min (μ i) (ν i)) * (ν j - min (μ j) (ν j)) / TVDist μ ν

omit [Fintype α] in
/-- The discrete metric is nonnegative. -/
lemma discreteMetric_nonneg : ∀ i j, (0 : ℝ) ≤ discreteMetric (α := α) i j := by
  exact fun i j => by unfold discreteMetric; split_ifs <;> norm_num;

omit [Fintype α] in
/-- The discrete metric vanishes on the diagonal. -/
lemma discreteMetric_diag : ∀ i, discreteMetric (α := α) i i = 0 := by
  exact fun i => if_pos rfl

omit [Fintype α] in
/-- The discrete metric is symmetric. -/
lemma discreteMetric_symm : ∀ i j, discreteMetric (α := α) i j = discreteMetric j i := by
  exact fun i j => by unfold discreteMetric; split_ifs <;> simp_all +decide [ eq_comm ] ;

omit [Fintype α] in
/-- The discrete metric satisfies the triangle inequality. -/
lemma discreteMetric_triangle : ∀ i j k, discreteMetric (α := α) i k ≤ discreteMetric i j + discreteMetric j k := by
  unfold discreteMetric; aesop;

omit [DecidableEq α] in
/-- The total bound: `∑ i, min (μ i) (ν i) + TVDist μ ν = 1` for probability vectors. -/
lemma sum_min_add_TVDist {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    (∑ i, min (μ i) (ν i)) + TVDist μ ν = 1 := by
  -- Using the pointwise identity `min a b = (a + b - |a - b|) / 2`, we can rewrite the sum of minima.
  have h_min_identity : ∑ i, min (μ i) (ν i) = (∑ i, (μ i + ν i - |μ i - ν i|)) / 2 := by
    rw [ Finset.sum_div _ _ _ ] ; congr ; ext i ; cases abs_cases ( μ i - ν i ) <;> cases min_cases ( μ i ) ( ν i ) <;> linarith;
  simp_all +decide [ Finset.sum_add_distrib, TVDist ];
  rw [ hμ.2, hν.2 ] ; ring

omit [DecidableEq α] in
lemma TVDist_nonneg (μ ν : α → ℝ) : 0 ≤ TVDist μ ν := by
  exact mul_nonneg ( by norm_num ) ( Finset.sum_nonneg fun _ _ => abs_nonneg _ )

/-- The discrete transport cost of a plan equals `1 - ∑ i, π i i`. -/
lemma discreteCost_eq {μ ν : α → ℝ} {π : α → α → ℝ}
    (hμ : IsProbDist μ) (hπ : IsCoupling μ ν π) :
    transportCost discreteMetric π = 1 - ∑ i, π i i := by
  unfold transportCost
  simp +decide [ *, discreteMetric, Finset.sum_ite, Finset.filter_ne, Finset.filter_eq, hπ.2.1, hμ.2 ]

/-- Lower bound: every plan costs at least the total variation distance. -/
lemma TVDist_le_discreteCost {μ ν : α → ℝ} {π : α → α → ℝ}
    (hμ : IsProbDist μ) (hν : IsProbDist ν) (hπ : IsCoupling μ ν π) :
    TVDist μ ν ≤ transportCost discreteMetric π := by
  rw [ discreteCost_eq hμ hπ ];
  -- By definition of $TVDist$, we know that $\sum_{i} \pi_{ii} \leq \sum_{i} \min(\mu_i, \nu_i)$.
  have h_sum_le : ∑ i, π i i ≤ ∑ i, min (μ i) (ν i) := by
    exact Finset.sum_le_sum fun i _ => le_min ( by simpa [ hπ.2.1 ] using Finset.single_le_sum ( fun j _ => hπ.1 i j ) ( Finset.mem_univ i ) ) ( by simpa [ hπ.2.2 ] using Finset.single_le_sum ( fun j _ => hπ.1 j i ) ( Finset.mem_univ i ) );
  linarith [ sum_min_add_TVDist hμ hν ]

/-- The proposed optimal plan is a valid coupling. -/
lemma tvCoupling_isCoupling {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    IsCoupling μ ν (tvCoupling μ ν) := by
  refine' ⟨ fun i j => _, fun i => _, fun j => _ ⟩;
  · refine' add_nonneg _ _;
    · split_ifs <;> [ exact le_min ( hμ.1 i ) ( hν.1 i ) ; exact le_rfl ];
    · exact div_nonneg ( mul_nonneg ( sub_nonneg.2 ( min_le_left _ _ ) ) ( sub_nonneg.2 ( min_le_right _ _ ) ) ) ( TVDist_nonneg _ _ );
  · by_cases h : TVDist μ ν = 0 <;> simp_all +decide [ tvCoupling ];
    · contrapose! h;
      exact ne_of_gt ( mul_pos ( by norm_num ) ( lt_of_lt_of_le ( abs_pos.mpr ( sub_ne_zero.mpr h.ne' ) ) ( Finset.single_le_sum ( fun a _ => abs_nonneg ( μ a - ν a ) ) ( Finset.mem_univ i ) ) ) );
    · simp +decide [ Finset.sum_add_distrib, mul_div_assoc ];
      simp +decide [ ← mul_div_assoc, ← Finset.sum_div, ← Finset.mul_sum _ _ _ ];
      rw [ show ∑ x, ν x - ∑ x, min ( μ x ) ( ν x ) = TVDist μ ν by linarith [ sum_min_add_TVDist hμ hν, hμ.2, hν.2 ] ] ; rw [ mul_div_cancel_right₀ _ h ] ; ring;
  · simp +decide [ tvCoupling, Finset.sum_add_distrib ];
    by_cases h : TVDist μ ν = 0 <;> simp_all +decide [ ← Finset.sum_div _ _ _, ← Finset.sum_mul ];
    · contrapose! h;
      exact ne_of_gt ( mul_pos ( by norm_num ) ( lt_of_lt_of_le ( abs_pos.mpr ( sub_ne_zero.mpr h.ne ) ) ( Finset.single_le_sum ( fun i _ => abs_nonneg ( μ i - ν i ) ) ( Finset.mem_univ j ) ) ) );
    · rw [ add_div', div_eq_iff ];
      · rw [ show TVDist μ ν = 1 - ∑ x, min ( μ x ) ( ν x ) by linarith [ sum_min_add_TVDist hμ hν ] ]
        rw [ hμ.2 ] ; ring;
      · exact h;
      · exact h

/-- The proposed optimal plan attains the total variation cost. -/
lemma tvCoupling_cost {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    transportCost discreteMetric (tvCoupling μ ν) = TVDist μ ν := by
  convert discreteCost_eq hμ ( tvCoupling_isCoupling hμ hν ) using 1;
  convert eq_sub_of_add_eq' ( sum_min_add_TVDist hμ hν ) using 1;
  simp +decide [ tvCoupling ];
  refine Finset.sum_congr rfl (fun i _ => ?_)
  rcases le_total (μ i) (ν i) with h | h
  · rw [min_eq_left h]; simp
  · rw [min_eq_right h]; simp

/-- **Wasserstein = total variation** for the discrete metric. -/
lemma Wass_discreteMetric_eq_TVDist {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    Wass discreteMetric μ ν = TVDist μ ν := by
  refine' le_antisymm _ _;
  · refine' csInf_le _ _;
    · exact costSet_bddBelow discreteMetric_nonneg;
    · exact ⟨ _, tvCoupling_isCoupling hμ hν, tvCoupling_cost hμ hν ⟩;
  · refine' le_csInf ( costSet_nonempty hμ hν ) _;
    rintro _ ⟨ π, hπ, rfl ⟩ ; exact TVDist_le_discreteCost hμ hν hπ;

omit [DecidableEq α] in
/-- The total variation distance vanishes exactly when the distributions agree. -/
lemma TVDist_eq_zero_iff {μ ν : α → ℝ} : TVDist μ ν = 0 ↔ μ = ν := by
  constructor <;> intro h;
  · exact funext fun i => sub_eq_zero.mp ( by contrapose! h; exact mul_ne_zero ( by norm_num ) ( ne_of_gt ( lt_of_lt_of_le ( abs_pos.mpr h ) ( Finset.single_le_sum ( fun i _ => abs_nonneg ( μ i - ν i ) ) ( Finset.mem_univ i ) ) ) ) );
  · unfold TVDist; aesop

/-- **Identity of indiscernibles**: for the discrete metric, `Wass` separates points,
so the Wasserstein distance is a genuine metric on the probability simplex. -/
lemma Wass_discreteMetric_eq_zero_iff {μ ν : α → ℝ} (hμ : IsProbDist μ) (hν : IsProbDist ν) :
    Wass discreteMetric μ ν = 0 ↔ μ = ν := by
  rw [ Wass_discreteMetric_eq_TVDist hμ hν, TVDist_eq_zero_iff ]

